//! Counter storage (`feature = "perf-counter"`).
//!
//! Plain `usize` counters are generated by [`define_counters!`]; special fields
//! and composite bump logic stay hand-written below.

use core::sync::atomic::Ordering;

use portable_atomic::{AtomicI32, AtomicU32, AtomicUsize};

/// Field + getter + `bump_*` + `reset_all` for monotonic `AtomicUsize` counters.
macro_rules! define_counters {
    ($($name:ident => $bump:ident),+ $(,)?) => {
        /// Monotonic counters for esp-radio hooks + xpost soft-fail paths.
        pub struct Counter {
            $( $name: AtomicUsize, )+
            tx_wifi_last_rc: AtomicI32,
            tx_pending_peak: AtomicUsize,
            tx_inflight_peak: AtomicUsize,
            tx_block_max_us: AtomicU32,
            block_since_us: AtomicU32,
        }

        impl Counter {
            pub const fn new() -> Self {
                Self {
                    $( $name: AtomicUsize::new(0), )+
                    tx_wifi_last_rc: AtomicI32::new(0),
                    tx_pending_peak: AtomicUsize::new(0),
                    tx_inflight_peak: AtomicUsize::new(0),
                    tx_block_max_us: AtomicU32::new(0),
                    block_since_us: AtomicU32::new(0),
                }
            }

            $(
                #[inline]
                pub fn $name(&self) -> usize {
                    self.$name.load(Ordering::Relaxed)
                }

                #[inline]
                pub(crate) fn $bump(&self) {
                    self.$name.fetch_add(1, Ordering::Relaxed);
                }
            )+

            pub fn reset_all(&self) {
                $( self.$name.store(0, Ordering::Relaxed); )+
                self.tx_wifi_last_rc.store(0, Ordering::Relaxed);
                self.tx_pending_peak.store(0, Ordering::Relaxed);
                self.tx_inflight_peak.store(0, Ordering::Relaxed);
                self.tx_block_max_us.store(0, Ordering::Relaxed);
                self.block_since_us.store(0, Ordering::Relaxed);
            }
        }
    };
}

define_counters! {
    rx_packets => bump_rx_packets,
    xdp_invocations => bump_xdp_invocations,
    xdp_pass => bump_xdp_pass,
    xdp_drop => bump_xdp_drop,
    xdp_tx => bump_xdp_tx,
    xdp_aborted => bump_xdp_aborted,
    rx_delivered => bump_rx_delivered,
    rx_discarded => bump_rx_discarded,
    rx_queue_overflow => bump_rx_queue_overflow,
    tx_submitted => bump_tx_submitted,
    tx_failed => bump_tx_failed_raw,
    tx_completed => bump_tx_completed_ok,
    runtime_errors => bump_runtime_error,
    tx_fail_bad_buf => bump_tx_fail_bad_buf,
    tx_fail_token => bump_tx_fail_token,
    tx_grp_src => bump_tx_grp_src,
    tx_enq => bump_tx_enq,
    tx_enq_fail_claim => bump_tx_enq_fail_claim,
    tx_enq_fail_ring => bump_tx_enq_fail_ring,
    tx_kick => bump_tx_kick,
    tx_poll => bump_tx_poll,
    tx_cap_wait => bump_tx_cap_wait_raw,
    tx_nomem_wait => bump_tx_nomem_wait_raw,
    tx_no_retain => bump_tx_no_retain,
    tx_flush => bump_tx_flush,
    tx_air_done_fail => bump_tx_air_done_fail,
    tx_ns_ref => bump_tx_ns_ref,
    tx_ns_free => bump_tx_ns_free,
    tx_flow_sample => bump_tx_flow_sample,
    tx_log_dropped => bump_tx_log_dropped,
    tx_block_gt10ms => bump_tx_block_gt10ms,
    tx_block_gt100ms => bump_tx_block_gt100ms,
    inactive_skip => bump_inactive_skip_raw,
    reentry => bump_reentry_raw,
    stack_misalign => bump_stack_misalign_raw,
    bad_md => bump_bad_md_raw,
    helper_unresolved => bump_helper_unresolved_raw,
    helper_map => bump_helper_map_raw,
    pool_drop_misalign => bump_pool_drop_misalign_raw,
}

impl Counter {
    #[inline]
    pub fn drop_count(&self) -> usize {
        self.rx_discarded()
    }

    #[inline]
    pub fn failed_tx_count(&self) -> usize {
        self.tx_fail_bad_buf() + self.tx_fail_token() + self.tx_failed()
    }

    #[inline]
    pub fn failed_tx_bad_buf_count(&self) -> usize {
        self.tx_fail_bad_buf()
    }

    #[inline]
    pub fn failed_tx_token_count(&self) -> usize {
        self.tx_fail_token()
    }

    #[inline]
    pub fn failed_tx_wifi_count(&self) -> usize {
        self.tx_failed()
    }

    #[inline]
    pub fn failed_tx_wifi_last_rc(&self) -> i32 {
        self.tx_wifi_last_rc.load(Ordering::Relaxed)
    }

    #[inline]
    pub fn tx_enq_claim(&self) -> usize {
        self.tx_enq_fail_claim()
    }

    #[inline]
    pub fn tx_enq_ring(&self) -> usize {
        self.tx_enq_fail_ring()
    }

    #[inline]
    pub fn tx_drain_ok(&self) -> usize {
        self.tx_submitted()
    }

    #[inline]
    pub fn tx_polls(&self) -> usize {
        self.tx_poll()
    }

    #[inline]
    pub fn tx_kicks(&self) -> usize {
        self.tx_kick()
    }

    #[inline]
    pub fn tx_done(&self) -> usize {
        self.tx_completed()
    }

    #[inline]
    pub fn tx_done_fail(&self) -> usize {
        self.tx_air_done_fail()
    }

    #[inline]
    pub fn tx_flow_samples(&self) -> usize {
        self.tx_flow_sample()
    }

    #[inline]
    pub fn tx_submit_fail(&self) -> usize {
        self.tx_failed()
    }

    #[inline]
    pub fn tx_pending_peak(&self) -> usize {
        self.tx_pending_peak.load(Ordering::Relaxed)
    }

    #[inline]
    pub fn tx_inflight_peak(&self) -> usize {
        self.tx_inflight_peak.load(Ordering::Relaxed)
    }

    #[inline]
    pub fn tx_block_max_us(&self) -> u32 {
        self.tx_block_max_us.load(Ordering::Relaxed)
    }

    #[inline]
    pub fn tx_pend(&self) -> usize {
        esp_radio::wifi::xdp_tx_pending()
    }

    #[inline]
    pub fn tx_inflight(&self) -> usize {
        esp_radio::wifi::xdp_tx_in_flight()
    }

    #[inline]
    pub fn tx_last_rc(&self) -> i32 {
        self.failed_tx_wifi_last_rc()
    }

    #[inline]
    pub fn tx_inflight_cap(&self) -> usize {
        esp_radio::wifi::xdp_tx_stats().inflight_cap as usize
    }

    /// Clear TX-path counters / peaks (formal round boundary).
    pub fn clear_tx(&self) {
        self.tx_fail_bad_buf.store(0, Ordering::Relaxed);
        self.tx_fail_token.store(0, Ordering::Relaxed);
        self.tx_failed.store(0, Ordering::Relaxed);
        self.tx_submitted.store(0, Ordering::Relaxed);
        self.tx_completed.store(0, Ordering::Relaxed);
        self.tx_wifi_last_rc.store(0, Ordering::Relaxed);
        self.tx_grp_src.store(0, Ordering::Relaxed);
        self.tx_enq.store(0, Ordering::Relaxed);
        self.tx_enq_fail_claim.store(0, Ordering::Relaxed);
        self.tx_enq_fail_ring.store(0, Ordering::Relaxed);
        self.tx_kick.store(0, Ordering::Relaxed);
        self.tx_poll.store(0, Ordering::Relaxed);
        self.tx_cap_wait.store(0, Ordering::Relaxed);
        self.tx_nomem_wait.store(0, Ordering::Relaxed);
        self.tx_no_retain.store(0, Ordering::Relaxed);
        self.tx_flush.store(0, Ordering::Relaxed);
        self.tx_air_done_fail.store(0, Ordering::Relaxed);
        self.tx_ns_ref.store(0, Ordering::Relaxed);
        self.tx_ns_free.store(0, Ordering::Relaxed);
        self.tx_flow_sample.store(0, Ordering::Relaxed);
        self.tx_log_dropped.store(0, Ordering::Relaxed);
        self.tx_pending_peak.store(0, Ordering::Relaxed);
        self.tx_inflight_peak.store(0, Ordering::Relaxed);
        self.tx_block_max_us.store(0, Ordering::Relaxed);
        self.tx_block_gt10ms.store(0, Ordering::Relaxed);
        self.tx_block_gt100ms.store(0, Ordering::Relaxed);
        self.block_since_us.store(0, Ordering::Relaxed);
    }

    #[inline]
    pub(crate) fn note_block_start(&self) {
        let t = esp_hal::time::Instant::now()
            .duration_since_epoch()
            .as_micros() as u32;
        let _ = self.block_since_us.compare_exchange(
            0,
            t.max(1),
            Ordering::Relaxed,
            Ordering::Relaxed,
        );
    }

    #[inline]
    pub(crate) fn note_block_end(&self) -> Option<u32> {
        let since = self.block_since_us.swap(0, Ordering::Relaxed);
        if since == 0 {
            return None;
        }
        let now = esp_hal::time::Instant::now()
            .duration_since_epoch()
            .as_micros() as u32;
        let dur = now.wrapping_sub(since);
        let _ = self
            .tx_block_max_us
            .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |m| {
                (dur > m).then_some(dur)
            });
        if dur > 10_000 {
            self.bump_tx_block_gt10ms();
        }
        if dur > 100_000 {
            self.bump_tx_block_gt100ms();
        }
        Some(dur)
    }

    #[inline]
    pub(crate) fn bump_xdp_action(&self, action: xpost_type::XdpAction) {
        match action {
            xpost_type::XdpAction::Pass => self.bump_xdp_pass(),
            xpost_type::XdpAction::Drop => self.bump_xdp_drop(),
            xpost_type::XdpAction::Tx => self.bump_xdp_tx(),
            xpost_type::XdpAction::Aborted => self.bump_xdp_aborted(),
        }
    }

    #[inline]
    pub(crate) fn bump_tx_failed(&self) {
        self.bump_tx_failed_raw();
        self.tx_wifi_last_rc.store(
            esp_radio::wifi::xdp_tx_last_drain_rc(),
            Ordering::Relaxed,
        );
    }

    #[inline]
    pub(crate) fn bump_tx_completed(&self, ok: bool) {
        if ok {
            self.bump_tx_completed_ok();
        } else {
            self.bump_tx_air_done_fail();
        }
    }

    #[inline]
    pub(crate) fn bump_tx_cap_wait(&self) {
        self.bump_tx_cap_wait_raw();
        self.note_block_start();
    }

    #[inline]
    pub(crate) fn bump_tx_nomem_wait(&self) {
        self.bump_tx_nomem_wait_raw();
        self.note_block_start();
    }

    #[inline]
    pub(crate) fn bump_tx_depth(&self, pending: usize, inflight: usize) {
        let _ = self
            .tx_pending_peak
            .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |m| {
                (pending > m).then_some(pending)
            });
        let _ = self
            .tx_inflight_peak
            .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |m| {
                (inflight > m).then_some(inflight)
            });
    }

    #[inline]
    pub(crate) fn inc_inactive_skip(&self) {
        self.bump_inactive_skip_raw();
        self.bump_runtime_error();
    }

    #[inline]
    pub(crate) fn inc_reentry(&self) {
        self.bump_reentry_raw();
        self.bump_runtime_error();
    }

    #[inline]
    pub(crate) fn inc_stack_misalign(&self) {
        self.bump_stack_misalign_raw();
        self.bump_runtime_error();
    }

    #[inline]
    pub(crate) fn inc_bad_md(&self) {
        self.bump_bad_md_raw();
        self.bump_runtime_error();
    }

    #[inline]
    pub(crate) fn inc_helper_unresolved(&self) {
        self.bump_helper_unresolved_raw();
        self.bump_runtime_error();
    }

    #[inline]
    pub(crate) fn inc_helper_map(&self) {
        self.bump_helper_map_raw();
        self.bump_runtime_error();
    }

    #[inline]
    pub(crate) fn inc_pool_drop_misalign(&self) {
        self.bump_pool_drop_misalign_raw();
        self.bump_runtime_error();
    }
}

#[inline]
pub(crate) fn inc_inactive_skip() {
    crate::xdp::ingress::XDP_PROG.counter.inc_inactive_skip();
}
#[inline]
pub(crate) fn inc_reentry() {
    crate::xdp::ingress::XDP_PROG.counter.inc_reentry();
}
#[inline]
pub(crate) fn inc_stack_misalign() {
    crate::xdp::ingress::XDP_PROG.counter.inc_stack_misalign();
}
#[inline]
pub(crate) fn inc_bad_md() {
    crate::xdp::ingress::XDP_PROG.counter.inc_bad_md();
}
#[inline]
pub(crate) fn inc_helper_unresolved() {
    crate::xdp::ingress::XDP_PROG.counter.inc_helper_unresolved();
}
#[inline]
pub(crate) fn inc_helper_map() {
    crate::xdp::ingress::XDP_PROG.counter.inc_helper_map();
}
#[inline]
pub(crate) fn inc_pool_drop_misalign() {
    crate::xdp::ingress::XDP_PROG.counter.inc_pool_drop_misalign();
}
